// Parked passenger cars for the V5 / V7 street sections: three original, generic body styles
// (compact hatchback, four-door saloon, compact SUV) generated by the geometry kit. They are not
// copies of any manufacturer's model and carry no badges. No asset download: about 1,000 triangles
// each, merged into the section's per-material buffers (one draw call per material for all cars).
//
// Local frame: +x forward, +y up, origin on the road under the middle of the car.
import { Kit, hex, shade, rnd } from './kit.ts';
import type { Col, V3 } from './kit.ts';

export type VehicleKind = 'hatch' | 'saloon' | 'suv';

interface Spec {
  /** Body stations from tail to nose: [x, half width, underside y, deck (bonnet / belt / boot) y]. */
  body: [number, number, number, number][];
  /** Glasshouse: rear glass foot x, roof rear x, roof front x, windscreen foot x, roof y, B-pillar x. */
  cab: { xr0: number; xr1: number; xf1: number; xf0: number; roof: number; xb: number; quarter: boolean };
  /** Rear and front axle x, wheel radius. */
  axles: [number, number]; rw: number;
}

const SPECS: Record<VehicleKind, Spec> = {
  hatch: {
    body: [[-1.95, 0.66, 0.34, 0.93], [-1.88, 0.79, 0.28, 0.97], [-1.7, 0.845, 0.24, 0.99], [-1.2, 0.86, 0.21, 1.0], [-0.2, 0.865, 0.2, 0.99], [0.7, 0.86, 0.2, 0.96],
      [1.1, 0.855, 0.21, 0.9], [1.5, 0.84, 0.23, 0.82], [1.76, 0.8, 0.26, 0.74], [1.9, 0.73, 0.28, 0.69], [1.95, 0.6, 0.29, 0.66]],
    cab: { xr0: -1.86, xr1: -1.48, xf1: 0.12, xf0: 0.84, roof: 1.5, xb: -0.25, quarter: true },
    axles: [-1.22, 1.22], rw: 0.29,
  },
  saloon: {
    body: [[-2.2, 0.62, 0.36, 0.9], [-2.13, 0.77, 0.3, 0.95], [-1.95, 0.83, 0.25, 0.98], [-1.35, 0.85, 0.21, 1.0], [-0.3, 0.855, 0.2, 0.98], [0.75, 0.85, 0.2, 0.95],
      [1.25, 0.845, 0.21, 0.88], [1.7, 0.83, 0.23, 0.8], [2.0, 0.79, 0.26, 0.73], [2.15, 0.72, 0.28, 0.68], [2.2, 0.59, 0.29, 0.65]],
    cab: { xr0: -1.5, xr1: -0.82, xf1: 0.15, xf0: 0.92, roof: 1.45, xb: -0.3, quarter: false },
    axles: [-1.3, 1.27], rw: 0.3,
  },
  suv: {
    body: [[-2.15, 0.7, 0.44, 1.08], [-2.08, 0.83, 0.38, 1.12], [-1.9, 0.89, 0.33, 1.14], [-1.3, 0.9, 0.29, 1.14], [-0.2, 0.905, 0.28, 1.12], [0.75, 0.9, 0.28, 1.09],
      [1.25, 0.895, 0.29, 1.03], [1.7, 0.88, 0.31, 0.96], [1.98, 0.84, 0.34, 0.9], [2.1, 0.77, 0.36, 0.85], [2.15, 0.64, 0.37, 0.82]],
    cab: { xr0: -2.06, xr1: -1.76, xf1: 0.25, xf0: 0.87, roof: 1.68, xb: -0.25, quarter: true },
    axles: [-1.3, 1.32], rw: 0.35,
  },
};

/** Footprint half length and half width (collision outline, spacing checks). */
export function vehicleSize(kind: VehicleKind): { half: number; hw: number } {
  const b = SPECS[kind].body;
  return { half: b[b.length - 1][0], hw: Math.max(...b.map((s) => s[1])) };
}

export interface PlateSource { rect(text: string, fg: string, bg: string, aspect: number, vertical?: boolean): [number, number, number, number] }

const BLACK = hex(0x151617), RUBBER = hex(0x17181a), GLASS = hex(0x10181c), ALLOY = hex(0xb4b7ba);
const CROWN = 0.035;

/** Convex polygon facing roughly `out` (winding fixed here so callers need not think about it). */
function face(k: Kit, pts: V3[], out: V3, col: Col, uvs?: [number, number][]): void {
  const a = pts[0], b = pts[1], c = pts[pts.length - 1];
  const ux = b[0] - a[0], uy = b[1] - a[1], uz = b[2] - a[2], vx = c[0] - a[0], vy = c[1] - a[1], vz = c[2] - a[2];
  const d = (uy * vz - uz * vy) * out[0] + (uz * vx - ux * vz) * out[1] + (ux * vy - uy * vx) * out[2];
  if (d < 0) { pts = pts.slice().reverse(); uvs = uvs?.slice().reverse(); }
  k.poly(pts, col, uvs);
}

/** Point on the bilinear patch a (u0 v0), b (u1 v0), c (u1 v1), d (u0 v1), pushed `off` along n. */
function bil(q: V3[], u: number, v: number, n: V3, off: number): V3 {
  const [a, b, c, d] = q, o: V3 = [0, 0, 0];
  for (let i = 0; i < 3; i++) o[i] = (a[i] * (1 - u) + b[i] * u) * (1 - v) + (d[i] * (1 - u) + c[i] * u) * v + n[i] * off;
  return o;
}
function pane(k: Kit, q: V3[], u0: number, u1: number, v0: number, v1: number, n: V3, off: number, col: Col): void {
  face(k, [bil(q, u0, v0, n, off), bil(q, u1, v0, n, off), bil(q, u1, v1, n, off), bil(q, u0, v1, n, off)], n, col);
}
function normalOf(q: V3[], out: V3): V3 {
  const [a, b, , d] = q;
  const ux = b[0] - a[0], uy = b[1] - a[1], uz = b[2] - a[2], vx = d[0] - a[0], vy = d[1] - a[1], vz = d[2] - a[2];
  let n: V3 = [uy * vz - uz * vy, uz * vx - ux * vz, ux * vy - uy * vx];
  const l = Math.hypot(n[0], n[1], n[2]) || 1;
  n = [n[0] / l, n[1] / l, n[2] / l];
  return n[0] * out[0] + n[1] * out[1] + n[2] * out[2] < 0 ? [-n[0], -n[1], -n[2]] : n;
}

/** Half cross-section [z, y] from the underside edge up to the centre of the deck. */
function halfRing(hw: number, bot: number, deck: number): [number, number][] {
  return [[hw - 0.12, bot], [hw - 0.03, bot + 0.05], [hw, bot + (deck - bot) * 0.45], [hw - 0.012, deck - 0.11], [hw - 0.04, deck - 0.035], [hw - 0.11, deck], [hw * 0.5, deck + CROWN * 0.75], [0, deck + CROWN]];
}

function wheel(k: Kit, rw: number): void {
  // local +y is the axle, pointing out of the car; y = 0 is the outer face of the tyre
  const rr = rw * 0.64;
  k.use('wire');
  k.lathe(0, 0, [[0, -0.19], [rw - 0.04, -0.19], [rw, -0.165], [rw, -0.03], [rw - 0.025, 0], [rr, 0]], 16, RUBBER);
  k.use('gold');
  k.lathe(0, 0, [[rr, 0], [rr - 0.02, -0.034], [0.05, -0.028], [0, -0.016]], 16, (j) => shade(ALLOY, j === 0 ? 1 : 0.8));
  k.use('wire');
  for (let i = 0; i < 5; i++) {
    const a = (i / 5) * Math.PI * 2, w0 = 0.42, w1 = 0.3, r0 = 0.075, r1 = rr - 0.035, y = -0.012;
    face(k, [[Math.cos(a - w0) * r0, y, Math.sin(a - w0) * r0], [Math.cos(a - w1) * r1, y, Math.sin(a - w1) * r1], [Math.cos(a + w1) * r1, y, Math.sin(a + w1) * r1], [Math.cos(a + w0) * r0, y, Math.sin(a + w0) * r0]], [0, 1, 0], BLACK);
  }
}

/** Build one parked car at the current kit transform. `plate` supplies number-plate text (optional). */
export function vehicle(k: Kit, kind: VehicleKind, body: Col, plate?: PlateSource | null, plateText = ''): void {
  const S = SPECS[kind], st = S.body, n = st.length, half = st[n - 1][0], cab = S.cab;
  const at = (x: number): { hw: number; bot: number; deck: number } => {
    let i = 1;
    while (i < n - 1 && st[i][0] < x) i++;
    const a = st[i - 1], b = st[i], t = Math.min(1, Math.max(0, (x - a[0]) / (b[0] - a[0])));
    return { hw: a[1] + (b[1] - a[1]) * t, bot: a[2] + (b[2] - a[2]) * t, deck: a[3] + (b[3] - a[3]) * t };
  };

  // --- lower body: smooth loft, coloured cell by cell so lamps and sills follow the surface -----------------
  const rings: V3[][] = st.map(([x, hw, bot, deck]) => {
    const h = halfRing(hw, bot, deck), r: V3[] = [];
    for (const [z, y] of h) r.push([x, y, -z]);
    for (let i = h.length - 2; i >= 0; i--) r.push([x, h[i][1], h[i][0]]);
    return r;
  });
  const M = rings[0].length;
  const nor: V3[][] = rings.map((r) => r.map(() => [0, 0, 0] as V3));
  for (let i = 0; i < n - 1; i++) for (let j = 0; j < M - 1; j++) {
    const a = rings[i][j], b = rings[i][j + 1], d = rings[i + 1][j];
    const ux = b[0] - a[0], uy = b[1] - a[1], uz = b[2] - a[2], vx = d[0] - a[0], vy = d[1] - a[1], vz = d[2] - a[2];
    const f: V3 = [uy * vz - uz * vy, uz * vx - ux * vz, ux * vy - uy * vx];
    for (const [p, q] of [[i, j], [i, j + 1], [i + 1, j], [i + 1, j + 1]]) { nor[p][q][0] += f[0]; nor[p][q][1] += f[1]; nor[p][q][2] += f[2]; }
  }
  for (const r of nor) for (const v of r) { const l = Math.hypot(v[0], v[1], v[2]) || 1; v[0] /= l; v[1] /= l; v[2] /= l; }
  const lampRed = hex(0x9a100c), lampClear = hex(0xdfe3e6);
  for (let i = 0; i < n - 1; i++) for (let j = 0; j < M - 1; j++) {
    const h = Math.min(j, M - 2 - j);
    if (h >= 5 && st[i][0] >= cab.xr0 + 0.04 && st[i + 1][0] <= cab.xf0 - 0.04) continue; // hidden under the glasshouse
    let col = body;
    if (h === 0) { k.use('wire'); col = BLACK; }
    else if ((h === 2 || h === 3) && i <= 1) { k.use('glass'); col = lampRed; }
    else if ((h === 2 || h === 3) && i >= n - 3) { k.use('glass'); col = lampClear; }
    else k.use('carpaint');
    const q = [[i, j], [i, j + 1], [i + 1, j + 1], [i + 1, j]].map(([p, r]) => k.v(rings[p][r], nor[p][r], col));
    k.tri(q[0], q[1], q[2]); k.tri(q[0], q[2], q[3]);
  }
  k.use('carpaint');
  face(k, rings[0], [-1, 0, 0], shade(body, 0.92));
  face(k, rings[n - 1], [1, 0, 0], body);
  k.use('wire');
  const under = Math.min(...st.map((s) => s[2])) + 0.03;
  face(k, [[-half + 0.1, under, -0.7], [half - 0.1, under, -0.7], [half - 0.1, under, 0.7], [-half + 0.1, under, 0.7]], [0, -1, 0], hex(0x0c0c0c));

  // --- nose and tail fittings (flat end faces) -------------------------------------------------------------
  const fr = st[n - 1], re = st[0], xf = half + 0.006, xr = -half - 0.006;
  const rectX = (x: number, y0: number, y1: number, zw: number, col: Col, uv?: [number, number, number, number]) => {
    const o: V3 = [Math.sign(x), 0, 0], z = Math.sign(x) * zw; // u runs left to right as seen from outside
    face(k, [[x, y0, z], [x, y0, -z], [x, y1, -z], [x, y1, z]], o, col, uv ? [[uv[0], uv[1]], [uv[2], uv[1]], [uv[2], uv[3]], [uv[0], uv[3]]] : undefined);
  };
  const gh = kind === 'suv' ? 0.17 : 0.12;
  rectX(xf, fr[3] - 0.02 - gh, fr[3] - 0.02, fr[1] - 0.2, BLACK);
  rectX(xf, fr[2] + 0.02, fr[2] + 0.11, fr[1] - 0.13, BLACK);
  rectX(xr, re[2] + 0.01, re[2] + 0.1, re[1] - 0.12, BLACK);
  k.use('gold');
  rectX(xf + 0.003, fr[3] - 0.02 - gh * 0.55, fr[3] - 0.02 - gh * 0.4, fr[1] - 0.26, ALLOY);
  const py = re[2] + (re[3] - re[2]) * 0.52;
  rectX(xr - 0.003, py + 0.075, py + 0.1, 0.3, ALLOY);
  const uv = plate && plateText ? plate.rect(plateText, '#f4f4f0', '#0b0b0c', 4) : undefined;
  k.use(uv ? 'sign' : 'wire');
  const pc = uv ? hex(0xffffff) : BLACK;
  rectX(xf + 0.004, fr[2] + 0.125, fr[2] + 0.235, 0.23, pc, uv);
  rectX(xr - 0.004, py - 0.055, py + 0.055, 0.23, pc, uv);

  // --- glasshouse: painted pillars and roof, black window surrounds, glass panes ------------------------------
  const yf0 = at(cab.xf0).deck, yr0 = at(cab.xr0).deck, wb = at(cab.xb).hw - 0.07, wt = wb - 0.13, roof = cab.roof;
  for (const s of [1, -1]) {
    const q: V3[] = [[cab.xr0, yr0, s * wb], [cab.xf0, yf0, s * wb], [cab.xf1, roof, s * wt], [cab.xr1, roof, s * wt]];
    const nq = normalOf(q, [0, 0, s]);
    k.use('carpaint');
    face(k, q, nq, body);
    const u0 = cab.quarter ? 0.05 : 0.11, u1 = 0.955;
    const ub = (cab.xb - (cab.xr0 + cab.xr1) / 2) / ((cab.xf0 + cab.xf1) / 2 - (cab.xr0 + cab.xr1) / 2);
    k.use('wire');
    pane(k, q, u0, u1, 0.07, 0.9, nq, 0.004, BLACK);
    k.use('glass');
    pane(k, q, ub + 0.014, u1 - 0.008, 0.09, 0.88, nq, 0.008, GLASS);
    if (cab.quarter) { const uq = u0 + 0.2; pane(k, q, u0 + 0.008, uq - 0.01, 0.09, 0.88, nq, 0.008, GLASS); pane(k, q, uq + 0.01, ub - 0.014, 0.09, 0.88, nq, 0.008, GLASS); }
    else pane(k, q, u0 + 0.008, ub - 0.014, 0.09, 0.88, nq, 0.008, GLASS);
    // door mirror, handles, shut lines
    k.use('carpaint');
    k.box(cab.xf0 - 0.2, cab.xf0 - 0.08, yf0 + 0.02, yf0 + 0.13, Math.min(s * (wb + 0.02), s * (wb + 0.2)), Math.max(s * (wb + 0.02), s * (wb + 0.2)), shade(body, 0.95));
    for (const xh of [cab.xb + 0.08, cab.xb - 0.82]) {
      const p = at(xh), z0 = s * (p.hw - 0.03), z1 = s * (p.hw + 0.006);
      k.box(xh, xh + 0.17, p.deck - 0.16, p.deck - 0.125, Math.min(z0, z1), Math.max(z0, z1), shade(body, 0.8));
    }
    k.use('wire');
    for (const xs of [cab.xb, S.axles[1] - S.rw - 0.2, S.axles[0] + S.rw + 0.14]) {
      const p = at(xs), h = halfRing(p.hw, p.bot, p.deck);
      for (let i = 1; i < 4; i++) face(k, [[xs - 0.006, h[i][1], s * (h[i][0] + 0.005)], [xs + 0.006, h[i][1], s * (h[i][0] + 0.005)], [xs + 0.006, h[i + 1][1], s * (h[i + 1][0] + 0.005)], [xs - 0.006, h[i + 1][1], s * (h[i + 1][0] + 0.005)]], [0, 0, s], BLACK);
    }
    // wheel arches (dark liner drawn on the flank) and wheels
    for (const xw of S.axles) {
      const p = at(xw), R = S.rw + 0.075, z = s * (p.hw + 0.004), a0 = Math.asin(Math.max(-1, (p.bot + 0.03 - S.rw) / R)), arc: V3[] = [];
      for (let i = 0; i <= 10; i++) { const a = a0 + ((Math.PI - 2 * a0) * i) / 10; arc.push([xw + Math.cos(a) * R, S.rw + Math.sin(a) * R, z]); }
      k.use('wire');
      face(k, arc, [0, 0, s], hex(0x0a0a0a));
      k.at({ x: xw, y: S.rw, z: s * (p.hw + 0.01), rx: (s * Math.PI) / 2 }, () => wheel(k, S.rw));
    }
  }
  const ws: V3[] = [[cab.xf0, yf0, -wb], [cab.xf0, yf0, wb], [cab.xf1, roof, wt], [cab.xf1, roof, -wt]], nw = normalOf(ws, [1, 1, 0]);
  const rs: V3[] = [[cab.xr0, yr0, wb], [cab.xr0, yr0, -wb], [cab.xr1, roof, -wt], [cab.xr1, roof, wt]], nr = normalOf(rs, [-1, 1, 0]);
  k.use('wire');
  face(k, ws, nw, BLACK); face(k, rs, nr, BLACK);
  k.use('glass');
  pane(k, ws, 0.035, 0.965, 0.06, 0.95, nw, 0.006, GLASS);
  pane(k, rs, 0.05, 0.95, 0.08, 0.93, nr, 0.006, GLASS);
  k.use('carpaint');
  const xm = (cab.xr1 + cab.xf1) / 2;
  k.grid([cab.xr1, xm, cab.xf1].map((x, i) => [-wt, -wt * 0.5, 0, wt * 0.5, wt].map((z, j) => [x, roof + (i === 1 ? 0.012 : 0) + CROWN * (1 - (Math.abs(j - 2) / 2) ** 2), z] as V3)), body);
  if (kind === 'suv') { k.use('wire'); for (const s of [1, -1]) k.box(cab.xr1 + 0.15, cab.xf1 - 0.15, roof + 0.015, roof + 0.05, s * (wt - 0.08) - 0.02, s * (wt - 0.08) + 0.02, BLACK); }

  // --- soft contact shadow on the road under the car -------------------------------------------------------
  k.use('contact');
  const bx = half + 0.3, bz = vehicleSize(kind).hw + 0.25;
  face(k, [[-bx, 0.016, -bz], [bx, 0.016, -bz], [bx, 0.016, bz], [-bx, 0.016, bz]], [0, 1, 0], [0, 0, 0], [[0, 0], [1, 0], [1, 1], [0, 1]]);
}

/** A plausible Sarawak (Kuching) registration: QA + letter + four digits. Invented, not a record of a real vehicle. */
export function plateFor(seed: number): string {
  const L = 'ABCDEFGHJKLMNPRSTUVWXY';
  return `QA${L[Math.floor(rnd(seed, 1) * L.length)]} ${1000 + Math.floor(rnd(seed, 2) * 8999)}`;
}
